INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_dej-7-zamorske-objevy_0','Kdo objevil roku 1492 Ameriku (pro Evropany)?',ARRAY['Kryštof Kolumbus','Marco Polo','James Cook','Vasco da Gama']::TEXT[],0,'Kolumbus doplul na Bahamy.',1,ARRAY[]::TEXT[],NULL,0,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_1','Do které země Kolumbus plul původně?',ARRAY['do Austrálie','do Indie','do Ruska','do Afriky']::TEXT[],1,'Hledal západní cestu do Indie.',1,ARRAY[]::TEXT[],NULL,1,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_2','Která země Kolumbovu cestu financovala?',ARRAY['Anglie','Francie','Španělsko','Portugalsko']::TEXT[],2,'Královna Isabela Kastilská.',1,ARRAY[]::TEXT[],NULL,2,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_3','Kdo doplul roku 1498 do Indie kolem Afriky?',ARRAY['Magalhães','Kolumbus','Vasco da Gama','Cortés']::TEXT[],2,'Portugalec.',2,ARRAY[]::TEXT[],NULL,3,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_4','Kdo vedl první výpravu kolem světa?',ARRAY['Kolumbus','Marco Polo','Fernão de Magalhães (Magellan)','James Cook']::TEXT[],2,'Plul pod španělskou vlajkou, zemřel na Filipínách.',2,ARRAY[]::TEXT[],NULL,4,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_5','Jak se nazývají obyvatelé Ameriky, které Evropané potkali?',ARRAY['Slované','Indiáni (původní obyvatelé)','Berbeři','Vikingové']::TEXT[],1,'Kolumbus je nazval Indiány.',2,ARRAY[]::TEXT[],NULL,5,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_6','Kdo dobyl aztécké impérium?',ARRAY['Kolumbus','Hernán Cortés','Vasco da Gama','Francisco Pizarro']::TEXT[],1,'Cortés dobyl Tenochtitlán (1521).',3,ARRAY[]::TEXT[],NULL,6,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_7','Kdo dobyl říši Inků?',ARRAY['Francisco Pizarro','Magalhães','Kolumbus','Hernán Cortés']::TEXT[],0,'Pizarro dobyl Inky (1532).',3,ARRAY[]::TEXT[],NULL,7,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_8','Co přinesla zámořská plavba do Evropy z Ameriky?',ARRAY['koně a ovce','hedvábí a čaj','brambory, kukuřici a rajčata','pšenici a ječmen']::TEXT[],2,'Plodiny z Nového světa.',3,ARRAY[]::TEXT[],NULL,8,'c_dej-7-zamorske-objevy',NULL,NOW()),
('q_dej-7-zamorske-objevy_9','Jaký byl hlavní důvod hledání nových cest do Indie?',ARRAY['hledání pěstování brambor','šíření islámu','boj proti Turkům na moři','obchod s kořením']::TEXT[],3,'Koření bylo velmi cenné.',4,ARRAY[]::TEXT[],NULL,9,'c_dej-7-zamorske-objevy',NULL,NOW()),
